'use strict';
const E=DataEngine;
const describeCache=new WeakMap(),baseDescribe=E.describe;
E.describe=(rows,c)=>{let cache=describeCache.get(rows);if(!cache){cache=new Map();describeCache.set(rows,cache);}if(!cache.has(c))cache.set(c,baseDescribe(rows,c));return cache.get(c);};
function inLang(lang,fn){const previous=state.lang;state.lang=lang;try{return fn();}finally{state.lang=previous;}}
const $=id=>document.getElementById(id);
const state={lang:localStorage.getItem('clearframe-language')||'zh',view:'overview',data:E.sample(),raw:E.sample(),name:'随机学生学习成绩_500行.csv',sample:true,history:[],snapshots:[],page:0,search:'',sort:null,filter:null,analysisTab:'describe',result:null,chart:{type:'line',x:'测试日期',y:'数学成绩',agg:'mean',group:'month'},overviewMetric:'数学成绩',menu:false,clean:{op:'dropMissing',column:'*',param:''}};
const t=(zh,en)=>state.lang==='zh'?zh:en;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nf=(v,d=0)=>v==null?'—':new Intl.NumberFormat(state.lang==='zh'?'zh-CN':'en-US',{maximumFractionDigits:d}).format(v);
const colors=['#7a9c63','#b5c79b','#d6dfc3','#e3e8d8','#a796bb','#d5b074','#729d96','#c89c8b'];
const columnNames={"学号": ["学号", "Student ID"], "测试日期": ["测试日期", "Test date"], "班级": ["班级", "Class"], "学习方式": ["学习方式", "Learning method"], "每周学习时长": ["每周学习时长", "Weekly study hours"], "平均睡眠时长": ["平均睡眠时长", "Average sleep hours"], "出勤率": ["出勤率", "Attendance rate"], "语文成绩": ["语文成绩", "Chinese score"], "数学成绩": ["数学成绩", "Math score"], "英语成绩": ["英语成绩", "English score"], "作业完成率": ["作业完成率", "Homework completion rate"], "课外活动时长": ["课外活动时长", "Extracurricular hours"]};
const valueNames={"一班": ["一班", "Class 1"], "二班": ["二班", "Class 2"], "三班": ["三班", "Class 3"], "四班": ["四班", "Class 4"], "五班": ["五班", "Class 5"], "自主学习": ["自主学习", "Independent study"], "线上课程": ["线上课程", "Online classes"], "小组学习": ["小组学习", "Group study"]};
const label=c=>state.sample&&columnNames[c]?t(...columnNames[c]):c;
const display=v=>E.missing(v)?t('缺失','Missing'):state.sample&&valueNames[v]?t(...valueNames[v]):typeof v==='number'?nf(v,2):String(v);
const typeLabel=k=>({number:t('数值','Number'),date:t('日期','Date'),text:t('文本','Text'),boolean:t('布尔','Boolean'),empty:t('空列','Empty')})[k];
const aggLabel=k=>({sum:t('求和','Sum'),mean:t('平均值','Mean'),count:t('计数','Count'),unique:t('去重计数','Unique count'),min:t('最小值','Minimum'),max:t('最大值','Maximum'),median:t('中位数','Median')})[k];
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',table:'M3 4h18v16H3z M3 9h18 M3 14h18 M9 4v16',clean:'m14 3 7 7-11 11H3v-7z M10 7l7 7 M3 21h18',chart:'M3 3v18h18 M7 14l4-5 4 3 6-8',bars:'M5 20V10 M12 20V4 M19 20v-7',help:'M9 9a3 3 0 1 1 5 2c-1 1-2 1-2 3 M12 17h.01 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',upload:'M12 16V3 m-5 5 5-5 5 5 M4 15v6h16v-6',download:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h8',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',search:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16 m6-2 6 6',dots:'M5 12h.01 M12 12h.01 M19 12h.01',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z m-4 10 3 3 5-6',check:'m5 12 4 4L19 6',rows:'M4 5h16 M4 10h16 M4 15h16 M4 20h16',columns:'M5 4v16 M10 4v16 M15 4v16 M20 4v16',warning:'m12 3 10 18H2z M12 9v5 M12 17h.01',bolt:'m13 2-9 12h7l-1 8 10-12h-7z',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',undo:'m8 3-5 5 5 5 M3 8h10a7 7 0 0 1 0 14',close:'m6 6 12 12 M6 18 18 6',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3c-5 5-5 13 0 18 5-5 5-13 0-18',leaf:'M20 3C6 2 2 9 6 17c8 6 16-1 14-14 M5 20 16 9',filter:'M3 4h18l-7 8v8l-4-2v-6z',arrow:'M4 12h16 m-6-6 6 6-6 6',trend:'m3 17 6-6 4 4 8-11 M15 4h6v6',code:'m8 7-5 5 5 5 m8-10 5 5-5 5 M14 3l-4 18',menu:'M3 6h18 M3 12h18 M3 18h18',plus:'M12 4v16 M4 12h16',image:'M3 3h18v18H3z m0 14 6-6 4 4 3-3 5 5 M8 7h.01'};
function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.grid}"/></svg>`;}
function options(cols,chosen,all=false){return (all?`<option value="*" ${chosen==='*'?'selected':''}>${t('所有列','All columns')}</option>`:'')+cols.map(c=>`<option value="${esc(c)}" ${c===chosen?'selected':''}>${esc(label(c))}</option>`).join('');}
function selectField(id,title,opts,note=''){return `<div class="field"><label for="${id}">${title}</label><select id="${id}">${opts}</select>${note?`<p>${note}</p>`:''}</div>`;}
function inputField(id,title,value='',placeholder=''){return `<div class="field"><label for="${id}">${title}</label><input id="${id}" value="${esc(value)}" placeholder="${esc(placeholder)}"></div>`;}
const aggs=(chosen='sum')=>['sum','mean','median','count','unique','min','max'].map(k=>`<option value="${k}" ${k===chosen?'selected':''}>${aggLabel(k)}</option>`).join('');
function validCols(){return state.data.columns.filter(c=>E.type(state.data.rows,c)==='number');}
function viewName(v){return ({overview:t('数据概览','Overview'),data:t('数据探索','Data explorer'),clean:t('数据清洗','Data preparation'),analysis:t('统计分析','Statistical analysis'),charts:t('可视化图表','Visualizations'),help:t('使用指南','Quick guide')})[v];}
function quality(){const {rows,columns}=state.data;let cells=0;columns.forEach(c=>cells+=rows.filter(r=>E.missing(r[c])).length);return {missing:cells,duplicates:E.duplicates(rows,columns),score:rows.length?100*(1-cells/(rows.length*columns.length)):0};}
function heading(){const descriptions={overview:t('让数据清晰，让发现自然发生。','A clearer view of your data. A better way to find what matters.'),data:t('筛选、排序与编辑，从每一行中发现细节。','Filter, sort and edit. Find the details in every row.'),clean:t('把不完美的数据，整理成可靠的分析起点。','Turn imperfect data into a dependable starting point.'),analysis:t('描述统计、分组聚合、透视表与相关性分析。','Descriptive statistics, grouping, pivot tables and correlations.'),charts:t('选择你的维度，用图形探索数据背后的故事。','Choose your dimensions. Explore the story behind the numbers.'),help:t('从导入到发现，用几个简单步骤完成分析。','From import to insight, in a few simple steps.')};return `<div class="page-heading"><div><div class="eyebrow">YOUR DATA, IN PERSPECTIVE</div><h1>${viewName(state.view)}</h1><p>${descriptions[state.view]}</p></div><div class="buttons"><button class="btn" data-action="export">${icon('download',15)}${t('导出数据','Export data')}</button><button class="btn primary" data-action="import">${icon('plus',16)}${t('导入数据','Import data')}</button></div></div>`;}
function datasetBar(){const n=state.data.rows.length;return `<div class="dataset-bar"><div class="dataset-main"><div class="file-icon">${icon('file',20)}</div><div><div class="dataset-name">${esc(state.name)} <span class="pill">${state.sample?t('示例数据','SAMPLE'):t('已导入','IMPORTED')}</span></div><div class="dataset-meta"><span>${nf(n)} ${t('行','rows')}</span><span>·</span><span>${state.data.columns.length} ${t('列','columns')}</span><span>·</span><span>${t('浏览器本地数据集','Local browser dataset')}</span></div></div></div><div class="dataset-right"><span><i class="status-dot"></i>${t('已就绪','Ready to explore')}</span><button class="btn small" data-action="import">${t('切换数据集','Change dataset')}${icon('down',12)}</button></div></div>`;}
function render(){document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';document.title=t('Clearframe · 数据分析工作台','Clearframe · Data studio');const nav=['overview','data','clean','analysis','charts'],navIcons=['grid','table','clean','bars','chart'];const q=quality();$('app').innerHTML=`<div class="app-shell"><aside class="sidebar ${state.menu?'open':''}"><div class="brand"><div class="brand-mark">${icon('bars',21)}</div>clearframe<small>.</small></div><div class="workspace-label">${t('分析工作空间','WORKSPACE')}</div><nav class="nav">${nav.map((v,i)=>`<button data-view="${v}" class="${state.view===v?'active':''}" ${state.view===v?'aria-current="page"':''}>${icon(navIcons[i],17)}${viewName(v)}${v==='clean'&&q.missing?`<span class="badge">${q.missing}</span>`:''}</button>`).join('')}</nav><div class="side-divider"></div><div class="side-project">${t('当前项目','CURRENT PROJECT')}<b>${t('我的数据分析','My data workspace')}</b><span>${t('探索 · 清洗 · 发现','Explore · Prepare · Discover')}</span></div><div class="side-footer"><nav class="nav"><button data-view="help" class="${state.view==='help'?'active':''}">${icon('help',17)}${t('使用指南','Quick guide')}</button></nav><div class="local-note">${icon('shield',17)}<span>${t('数据仅在浏览器中处理<br>由你掌握每一次分析','Your data stays in your browser.<br>Your analysis, in your hands.')}</span></div><div class="avatar-row"><div class="avatar">C</div><div>${t('个人工作空间','Personal workspace')}<div style="font-size:9px;color:#739180;margin-top:4px">${t('本地分析模式','LOCAL ANALYSIS')}</div></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu" data-action="menu" aria-label="${t('展开菜单','Toggle menu')}">${icon('menu',18)}</button><span>${t('工作空间','Workspace')}</span>${icon('chevron',11)}<b>${viewName(state.view)}</b></div><div class="top-actions"><span class="top-status"><i class="status-dot"></i>${t('数据在本地安全处理','Processed locally')}</span><button class="language" data-action="language" aria-label="${t('切换至英文','Switch to Chinese')}">${icon('globe',13)} ${state.lang==='zh'?'中 / EN':'EN / 中'}</button><button class="icon-button" data-view="help" aria-label="${t('帮助','Help')}">${icon('help',18)}</button><div class="avatar" style="width:29px;height:29px;font-size:10px;background:#edf2e5">C</div></div></header><div class="content">${heading()}${state.view!=='help'?datasetBar():''}<div id="view-content">${({overview:overview,data:dataView,clean:cleanView,analysis:analysisView,charts:chartsView,help:helpView})[state.view]()}</div><div class="footer"><span>${icon('leaf',12)} Clearframe · ${t('让每一份数据，都有清晰的表达','A clearer perspective on every dataset')}</span><span>${t('浏览器本地运行','Runs locally in your browser')} &nbsp;·&nbsp; ${t('参考 pandas 分析流程','Inspired by pandas workflows')}</span></div></div></main></div>`;bindView();}
function metric(title,value,note,ico,tag='',warn=false){return `<div class="metric"><div class="metric-top">${title}<div class="metric-icon">${icon(ico,16)}</div></div><div class="metric-value">${value}</div><div class="metric-bottom">${tag?`<span class="tag ${warn?'warn':''}">${tag}</span>`:''}<span>${note}</span></div></div>`;}
function overview(){const {rows,columns}=state.data,q=quality(),nums=validCols();if(!nums.includes(state.overviewMetric))state.overviewMetric=nums[0];const value=state.overviewMetric,key=columns.find(c=>E.type(rows,c)==='date')||columns.find(c=>E.type(rows,c)==='text'&&E.describe(rows,c).unique<=20)||columns[0],cat=columns.includes('category')?'category':columns.find(c=>E.type(rows,c)==='text'&&E.describe(rows,c).unique>1&&E.describe(rows,c).unique<=30)||columns[0];const trend=value?chartSeries(rows,key,value,'sum','month'):[],groups=value?E.group(rows,cat,value,'sum').sort((a,b)=>(b.value||0)-(a.value||0)):[],stats=value?E.describe(rows,value):{};return `<div class="metrics">${metric(t('数据行数','Total rows'),nf(rows.length),t('完整展示每一条记录','Every record, in one workspace'),'rows',t('记录','records'))}${metric(t('数据字段','Data columns'),columns.length,t(`${nums.length} 个数值型字段`,`${nums.length} numeric columns`),'columns',t('自动识别','Auto-detected'))}${metric(value?`${label(value)} · ${t('总计','total')}`:t('非空单元格','Non-empty cells'),value?nf(stats.sum??0):nf(rows.length*columns.length-q.missing),value?`${t('均值','Mean')} ${nf(stats.mean,1)}`:t('有效数据概览','Valid data summary'),'bars',value?t('Σ 求和','Σ SUM'):'')}${metric(t('数据完整度','Data completeness'),`${nf(q.score,1)}<span style="font-size:17px">%</span>`,t(`${q.missing} 个缺失值 · ${q.duplicates} 条重复记录`,`${q.missing} missing cells · ${q.duplicates} duplicate rows`),'shield',q.missing?t('待优化','To improve'):t('完整','Complete'),!!q.missing)}</div><div class="section-line"><h2>${icon('chart',16)}${t('从数据，到洞察','From data to insight')}</h2><span>${t('实时计算 · 悬停查看数值','Live calculations · Hover for details')}</span></div><div class="chart-grid"><section class="card"><div class="card-header"><div><div class="card-title">${value?label(value):t('记录数','Records')} ${t('趋势','over time')}</div><div class="card-subtitle">${t('按日期或维度汇总，观察数据变化','Aggregated by date or dimension to reveal patterns')}</div></div><select class="chart-select" id="overview-metric" aria-label="${t('选择指标','Select metric')}">${options(nums,value)}</select></div><div class="chart-wrap">${trend.length?lineChart(trend,label(value),'overview-trend'):emptySVG(t('导入数值列以查看趋势','Import numeric columns to explore trends'))}</div><div class="legend"><span><i style="background:#7a9c63"></i>${esc(label(value||key))}</span><span>${t('汇总方式：求和','Aggregation: sum')}</span></div><div class="chart-footer">${icon('bolt',12)}${t('每次更新数据，图表都会自动同步','Charts update automatically whenever your data changes')}</div></section><section class="card"><div class="card-header"><div><div class="card-title">${esc(label(cat))} ${t('贡献分布','breakdown')}</div><div class="card-subtitle">${t('用占比发现主要组成部分','Discover what contributes to the whole')}</div></div><span class="pill">${groups.length} ${t('分组','GROUPS')}</span></div><div class="chart-wrap">${donutChart(groups,label(value||cat),'overview-donut')}</div><div class="donut-key">${donutGroups(groups).map((g,i)=>`<span><i style="background:${colors[i%colors.length]}"></i>${esc(display(g.key))}<b style="margin-left:auto;font-weight:400">${nf(groups.reduce((a,b)=>a+Math.max(0,b.value||0),0)?100*Math.max(0,g.value||0)/groups.reduce((a,b)=>a+Math.max(0,b.value||0),0):0,1)}%</b></span>`).join('')}</div></section></div><div class="bottom-grid"><section class="card"><div class="table-toolbar"><div class="table-title">${t('数据预览','Data preview')}<small>${t('前 5 行','First 5 rows')}</small></div><button class="tool-link" data-view="data">${t('查看全部','View all')} ${icon('arrow',13)}</button></div>${tableHTML(rows.slice(0,5),columns.slice(0,6))}<div class="table-footer"><span>${t(`共 ${nf(rows.length)} 行，${columns.length} 列`,`Showing a dataset of ${nf(rows.length)} rows and ${columns.length} columns`)}</span><span>${t('点击探索，开始分析','Explore to get started')}</span></div></section><section class="card"><div class="card-header"><div class="card-title">${t('值得关注的发现','A few things worth exploring')}</div>${icon('bolt',16)}</div>${insights(groups,stats,value,q)}<div class="insight-action"><button data-view="analysis">${t('深入分析数据','Go deeper into your data')} ${icon('arrow',13)}</button></div></section></div>`;}
function insights(groups,stats,value,q){const top=groups[0],total=groups.reduce((a,b)=>a+(b.value||0),0);return `<div class="insight-list"><div class="insight"><div class="insight-icon">${icon('trend',15)}</div><div><h3>${t('找到贡献最大的分组','Find the largest contributor')}</h3><p>${top?t(`${esc(display(top.key))} 贡献了 <em>${nf(total?top.value/total*100:0,1)}%</em> 的${esc(label(value))}。`,`${esc(display(top.key))} contributes <em>${nf(total?top.value/total*100:0,1)}%</em> of ${esc(label(value))}.`):t('导入数据后，自动生成分组洞察。','Import data to generate grouping insights.')}</p></div></div><div class="insight"><div class="insight-icon">${icon('bars',15)}</div><div><h3>${t('关注数值的分布范围','Understand the range')}</h3><p>${value?t(`${esc(label(value))}从 <em>${nf(stats.min)}</em> 到 <em>${nf(stats.max)}</em>，中位数为 ${nf(stats.median,1)}。`,`${esc(label(value))} ranges from <em>${nf(stats.min)}</em> to <em>${nf(stats.max)}</em>, with a median of ${nf(stats.median,1)}.`):t('添加数值列，查看分布统计。','Add numeric columns to see distribution statistics.')}</p></div></div><div class="insight warning"><div class="insight-icon">${icon('warning',15)}</div><div><h3>${t('让分析从可靠的数据开始','Start with dependable data')}</h3><p>${t(`发现 ${q.missing} 个缺失值和 ${q.duplicates} 条重复记录，可在数据清洗中一键处理。`,`Found ${q.missing} missing cells and ${q.duplicates} duplicate rows. Prepare your data with a few clicks.`)}</p></div></div></div>`;}
function tableHTML(rows,columns,editable=false,offset=0){return `<div class="table-scroll"><table><thead><tr><th style="width:35px">#</th>${columns.map(c=>`<th>${editable?`<button data-sort="${esc(c)}" title="${t('点击排序','Click to sort')}">${esc(label(c))} ${state.sort?.c===c?(state.sort.dir===1?'↑':'↓'):'↕'}</button>`:esc(label(c))}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map((r,i)=>`<tr><td class="row-number">${String(offset+i+1).padStart(2,'0')}</td>${columns.map(c=>`<td>${editable?`<button class="cell-edit" data-edit="${state.data.rows.indexOf(r)}" data-column="${esc(c)}" title="${t('点击编辑','Click to edit')}">${cellValue(r[c],c)}</button>`:cellValue(r[c],c)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${columns.length+1}" class="empty">${t('没有匹配的记录','No matching records')}</td></tr>`}</tbody></table></div>`;}
function cellValue(v,c){if(E.missing(v))return `<span class="missing">—</span>`;return ['班级','学习方式'].includes(c)&&state.sample?`<span class="category-tag">${esc(display(v))}</span>`:esc(display(v));}
function filtered(){let rows=state.data.rows;if(state.filter)rows=E.filterRows(rows,...state.filter);if(state.search)rows=rows.filter(r=>state.data.columns.some(c=>String(r[c]??'').toLowerCase().includes(state.search.toLowerCase())||display(r[c]).toLowerCase().includes(state.search.toLowerCase())));if(state.sort){const {c,dir}=state.sort;rows=[...rows].sort((a,b)=>{if(E.missing(a[c]))return E.missing(b[c])?0:1;if(E.missing(b[c]))return-1;return dir*(E.number(a[c])&&E.number(b[c])?Number(a[c])-Number(b[c]):String(a[c]).localeCompare(String(b[c]),state.lang==='zh'?'zh':'en'));});}return rows;}
function filterOptions(chosen){return ['contains','eq','neq','gt','gte','lt','lte','missing','present'].map(k=>`<option value="${k}" ${chosen===k?'selected':''}>${({contains:t('包含','Contains'),eq:t('等于','Equals'),neq:t('不等于','Not equal'),gt:t('大于','Greater than'),gte:t('大于等于','At least'),lt:t('小于','Less than'),lte:t('小于等于','At most'),missing:t('为空','Is missing'),present:t('非空','Is present')})[k]}</option>`).join('');}
function dataView(){return `<section class="card"><div class="table-toolbar"><div class="table-title">${t('数据表','Data table')}<span class="step-count">${t('点击单元格即可编辑','Click a cell to edit')}</span></div><div class="search">${icon('search',13)}<input id="data-search" aria-label="${t('搜索数据','Search data')}" value="${esc(state.search)}" placeholder="${t('搜索所有字段…','Search all columns…')}"></div></div><div class="filter-row">${selectField('filter-col',t('筛选字段','Filter column'),options(state.data.columns,state.filter?.[0]))}${selectField('filter-op',t('条件','Condition'),filterOptions(state.filter?.[1]||'contains'))}${inputField('filter-value',t('筛选值','Value'),state.filter?.[2]||'',t('输入筛选值','Enter a value'))}<button class="btn primary" data-action="filter">${icon('filter',13)}${t('应用筛选','Apply')}</button><button class="btn" data-action="clear-filter">${t('清除','Clear')}</button><button class="btn" data-action="keep-filter">${t('保留筛选结果','Keep filtered rows')}</button></div><div id="data-table">${dataTableContent()}</div></section><div class="section-line"><h2>${t('字段画像','Column profiles')}</h2><span>${t('自动推断字段类型与完整度','Automatically detected types and completeness')}</span></div><section class="card">${profileTable()}</section>`;}
function dataTableContent(){const rows=filtered(),limit=12;state.page=Math.max(0,Math.min(state.page,Math.max(0,Math.ceil(rows.length/limit)-1)));return tableHTML(rows.slice(state.page*limit,(state.page+1)*limit),state.data.columns,true,state.page*limit)+`<div class="table-footer"><span>${t(`显示 ${rows.length?state.page*limit+1:0}–${Math.min((state.page+1)*limit,rows.length)} 行，共 ${nf(rows.length)} 条结果`,`Showing ${rows.length?state.page*limit+1:0}–${Math.min((state.page+1)*limit,rows.length)} of ${nf(rows.length)} results`)}</span><div class="buttons"><button class="btn small" data-action="prev" ${state.page===0?'disabled':''}>${t('上一页','Previous')}</button><span>${state.page+1} / ${Math.max(1,Math.ceil(rows.length/limit))}</span><button class="btn small" data-action="next" ${(state.page+1)*limit>=rows.length?'disabled':''}>${t('下一页','Next')}</button></div></div>`;}
function profileTable(){return `<div class="table-scroll"><table><thead><tr>${[t('字段','Column'),t('类型','Type'),t('有效值','Valid'),t('缺失值','Missing'),t('唯一值','Unique'),t('完整度','Completeness')].map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${state.data.columns.map(c=>{const d=E.describe(state.data.rows,c);return `<tr><td>${esc(label(c))}</td><td><span class="category-tag">${typeLabel(E.type(state.data.rows,c))}</span></td><td>${nf(d.count)}</td><td>${nf(d.missing)}</td><td>${nf(d.unique)}</td><td><div style="display:flex;align-items:center;gap:10px"><div class="progress-track" style="width:85px"><i style="width:${state.data.rows.length?100*d.count/state.data.rows.length:0}%"></i></div>${nf(state.data.rows.length?100*d.count/state.data.rows.length:0,1)}%</div></td></tr>`;}).join('')}</tbody></table></div>`;}
const cleanOps=['dropMissing','fillMean','fillMedian','fillMode','fillValue','dedupe','trim','number','text','rename','dropColumn'];
function opLabel(k){return ({dropMissing:t('删除缺失值所在行','Drop rows with missing values'),fillMean:t('使用均值填充','Fill with mean'),fillMedian:t('使用中位数填充','Fill with median'),fillMode:t('使用众数填充','Fill with mode'),fillValue:t('使用指定值填充','Fill with a custom value'),dedupe:t('删除重复行','Remove duplicate rows'),trim:t('去除首尾空格','Trim whitespace'),number:t('转换为数值','Convert to number'),text:t('转换为文本','Convert to text'),rename:t('重命名字段','Rename column'),dropColumn:t('删除字段','Drop column')})[k];}
function cleanParamField(){const c=state.clean;if(!['fillValue','rename'].includes(c.op))return '';return inputField('clean-param',c.op==='rename'?t('新字段名称','New column name'):t('指定填充值','Custom fill value'),c.param,c.op==='rename'?t('输入唯一的新名称','Enter a unique name'):t('输入填充值','Enter a fill value'));}
function cleanView(){const q=quality(),clean=state.clean;if(clean.column!=='*'&&!state.data.columns.includes(clean.column))clean.column=state.data.columns[0]||'*';return `<div class="panel-grid"><section class="card control-card"><h2>${t('清洗操作','Prepare your data')}</h2>${selectField('clean-op',t('选择操作','Operation'),cleanOps.map(k=>`<option value="${k}" ${k===clean.op?'selected':''}>${opLabel(k)}</option>`).join(''))}${selectField('clean-col',t('目标字段','Target column'),options(state.data.columns,clean.column,true))}<div id="clean-param-field">${cleanParamField()}</div><button class="btn primary" data-action="clean">${icon('check',15)}${t('应用操作','Apply operation')}</button><button class="btn" data-action="compute-open">${icon('plus',15)}${t('创建计算列','Create computed column')}</button><button class="btn" data-action="undo" ${state.snapshots.length?'':'disabled'}>${icon('undo',15)}${t('撤销上一步','Undo last step')}</button><div class="info-box">${t('选择操作后，使用“应用操作”更新数据。每一步都会记录，可随时撤销。数值转换失败的内容将设为空值。','Select an operation and apply it to your data. Each step is recorded and can be undone. Invalid numeric conversions become missing values.')}</div><div class="sql-preview">df.dropna() · df.fillna()<br>df.drop_duplicates()<br>df.rename() · df.astype()</div></section><div><section class="card"><div class="card-header"><div><div class="card-title">${t('数据质量检查','Data quality check')}</div><div class="card-subtitle">${t('先观察质量，再决定如何处理','Review the quality before choosing your next step')}</div></div><span class="pill">${nf(q.score,1)}%</span></div><div class="quality-bars">${state.data.columns.map(c=>{const valid=state.data.rows.length-E.describe(state.data.rows,c).missing,p=state.data.rows.length?100*valid/state.data.rows.length:0;return `<div class="quality-row"><span>${esc(label(c))}</span><div class="progress-track"><i style="width:${p}%"></i></div><span>${nf(p,1)}%</span></div>`;}).join('')}</div><div class="chart-footer">${icon('warning',13)}${t(`${q.missing} 个缺失单元格 · ${q.duplicates} 条完全重复的记录`,`${q.missing} missing cells · ${q.duplicates} exact duplicate rows`)}</div></section><section class="card" style="margin-top:20px"><div class="card-header"><div class="card-title">${t('操作流水线','Transformation history')}</div><span class="step-count">${state.history.length} ${t('步','steps')}</span></div><div class="history-list">${state.history.length?state.history.map((h,i)=>`<div class="history-row"><div class="insight-icon">${icon('check',14)}</div><div><b style="font-weight:500">${i+1}. ${t(h.zh,h.en)}</b><p style="font-size:10px;color:#9ba68e;margin-top:5px">${nf(h.before)} → ${nf(h.after)} ${t('行','rows')}</p></div><small>${h.time}</small></div>`).join(''):`<div class="empty">${icon('clean',26)}<br>${t('你的分析，从第一步清洗开始','Your first transformation will appear here')}</div>`}</div><div class="chart-footer">${icon('clock',12)}${t('本次会话的操作记录 · 最多可撤销 20 步','Session history · Undo up to 20 steps')}</div></section></div></div>`;}
function analysisView(){const tabs=['describe','group','pivot','correlation'];return `<div class="view-tabs" role="tablist">${tabs.map(k=>`<button data-tab="${k}" role="tab" aria-selected="${state.analysisTab===k}" class="${state.analysisTab===k?'active':''}">${({describe:t('描述统计','Describe'),group:t('分组聚合','Group by'),pivot:t('透视表','Pivot table'),correlation:t('相关性','Correlation')})[k]}</button>`).join('')}</div>${({describe:describeView,group:groupView,pivot:pivotView,correlation:correlationView})[state.analysisTab]()}`;}
function describeView(){const stats=['count','missing','unique','sum','mean','std','min','q25','median','q75','max'];const names={count:t('有效数量','Count'),missing:t('缺失数量','Missing'),unique:t('唯一值数','Unique'),sum:t('总和','Sum'),mean:t('均值','Mean'),std:t('标准差','Std. dev.'),min:t('最小值','Min'),q25:'25%',median:t('中位数','Median'),q75:'75%',max:t('最大值','Max')};return `<section class="card"><div class="table-toolbar"><div class="table-title">${t('描述性统计','Descriptive statistics')}<small>df.describe()</small></div><button class="btn small" data-action="export-analysis">${icon('download',13)}${t('导出统计','Export statistics')}</button></div><div class="table-scroll"><table><thead><tr><th>${t('统计量','Statistic')}</th>${state.data.columns.map(c=>`<th>${esc(label(c))}<div style="font-size:9px;margin-top:5px">${typeLabel(E.type(state.data.rows,c))}</div></th>`).join('')}</tr></thead><tbody>${stats.map(k=>`<tr><td>${names[k]}</td>${state.data.columns.map(c=>`<td>${nf(E.describe(state.data.rows,c)[k],2)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="chart-footer">${icon('help',13)}${t('数值统计忽略缺失值；标准差使用样本标准差（ddof=1）；分位数采用线性插值。','Numeric statistics skip missing values. Standard deviation uses ddof=1; quantiles use linear interpolation.')}</div></section>`;}
function groupView(){const nums=validCols();return `<div class="panel-grid"><section class="card control-card"><h2>${t('分组与聚合','Group & aggregate')}</h2>${selectField('group-key',t('分组维度','Group by'),options(state.data.columns,state.result?.kind==='group'?state.result.key:state.data.columns.includes('班级')?'班级':state.data.columns.includes('region')?'region':state.data.columns[0]))}${selectField('group-val',t('分析指标','Value column'),options(state.data.columns,state.result?.kind==='group'?state.result.value:nums.includes('数学成绩')?'数学成绩':nums.includes('revenue')?'revenue':nums[0]||state.data.columns[0]))}${selectField('group-agg',t('聚合方式','Aggregation'),aggs(state.result?.kind==='group'?state.result.agg:'sum'))}<button class="btn primary" data-action="group">${icon('bars',15)}${t('生成分析','Run analysis')}</button><div class="info-box">${t('比较不同分组的表现。求和、均值等数值操作请使用数值字段；文本字段可使用计数或去重计数。','Compare performance across groups. Use numeric columns for sum or mean, and count or unique count for text columns.')}</div><div class="sql-preview">df.groupby(key)[value].agg(method)</div></section><div id="analysis-result">${state.result?.kind==='group'?groupResultHTML():`<section class="card"><div class="empty">${icon('bars',36)}<br>${t('选择维度与指标，生成分组分析','Choose a dimension and metric to compare groups')}</div></section>`}</div></div>`;}
function groupResultHTML(){const r=state.result,gKey=label(r.key),gVal=label(r.value)+' · '+aggLabel(r.agg),gCount=t('记录数','Records');return `<section class="card wide-chart"><div class="card-header"><div><div class="card-title">${esc(label(r.key))} × ${esc(label(r.value))}</div><div class="card-subtitle">${aggLabel(r.agg)} · ${r.groups.length} ${t('个分组','groups')}</div></div><button class="btn small" data-action="export-analysis">${icon('download',13)}${t('导出','Export')}</button></div><div class="chart-wrap">${barChart(r.groups,'group-chart')}</div>${tableHTML(r.groups.map(g=>({[gKey]:g.key,[gVal]:g.value,[gCount]:g.count})),[gKey,gVal,gCount])}<div class="chart-footer">${t('图表最多展示前 30 组，表格与导出保留全部结果。','The chart shows up to 30 groups; the table and export include all results.')}</div></section>`;}
function pivotView(){const cols=state.data.columns;return `<div class="panel-grid"><section class="card control-card"><h2>${t('创建数据透视表','Build a pivot table')}</h2>${selectField('pivot-row',t('行维度','Rows'),options(cols,state.result?.kind==='pivot'?state.result.row:cols.includes('班级')?'班级':cols.includes('region')?'region':cols[0]))}${selectField('pivot-col',t('列维度','Columns'),options(cols,state.result?.kind==='pivot'?state.result.col:cols.includes('学习方式')?'学习方式':cols.includes('category')?'category':cols[1]||cols[0]))}${selectField('pivot-val',t('数值字段','Values'),options(cols,state.result?.kind==='pivot'?state.result.value:cols.includes('数学成绩')?'数学成绩':validCols()[0]||cols[0]))}${selectField('pivot-agg',t('聚合方式','Aggregation'),aggs(state.result?.kind==='pivot'?state.result.agg:'sum'))}<button class="btn primary" data-action="pivot">${icon('table',15)}${t('生成透视表','Create pivot')}</button><div class="info-box">${t('把两个分类维度交叉，发现结构中的差异。单元格颜色越深，数值越大。最多支持 50 × 50 个分组。','Cross two dimensions to reveal patterns. Darker cells indicate larger values. Supports up to 50 × 50 groups.')}</div><div class="sql-preview">df.pivot_table(index, columns,<br>values, aggfunc)</div></section><div id="analysis-result">${state.result?.kind==='pivot'?pivotResultHTML():`<section class="card"><div class="empty">${icon('table',36)}<br>${t('创建你的第一张透视表','Create your first pivot table')}</div></section>`}</div></div>`;}
function pivotResultHTML(){const r=state.result,max=Math.max(1,...r.matrix.flat().filter(Number.isFinite));return `<section class="card"><div class="table-toolbar"><div class="table-title">${esc(label(r.row))} × ${esc(label(r.col))}</div><button class="btn small" data-action="export-analysis">${icon('download',13)}${t('导出','Export')}</button></div><div class="result-note">${esc(label(r.value))} · ${aggLabel(r.agg)}</div><div class="table-scroll"><table><thead><tr><th>${esc(label(r.row))}</th>${r.colKeys.map(c=>`<th>${esc(display(c))}</th>`).join('')}</tr></thead><tbody>${r.rowKeys.map((k,i)=>`<tr><td>${esc(display(k))}</td>${r.matrix[i].map(v=>`<td class="correlation-cell" style="background:rgba(126,160,97,${v===null?0:Math.max(0,Math.min(.75,(v/max)*.65+.05))})">${nf(v,2)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="heatmap-note">${t('— 表示该组合没有有效值。','— indicates a combination without valid values.')}</div></section>`;}
function correlationView(){const nums=validCols();return `<section class="card"><div class="table-toolbar"><div class="table-title">${t('相关性矩阵','Correlation matrix')}<small>Pearson · df.corr()</small></div><button class="btn small" data-action="export-analysis">${icon('download',13)}${t('导出矩阵','Export matrix')}</button></div>${nums.length?`<div class="table-scroll"><table><thead><tr><th></th>${nums.map(c=>`<th>${esc(label(c))}</th>`).join('')}</tr></thead><tbody>${nums.map(a=>`<tr><td>${esc(label(a))}</td>${nums.map(b=>{const v=E.correlation(state.data.rows,a,b);return `<td class="correlation-cell" style="background:${v===null?'#f9faf6':v<0?`rgba(185,138,100,${Math.abs(v)*.6+.05})`:`rgba(126,160,97,${Math.abs(v)*.6+.05})`}" title="${esc(label(a))} × ${esc(label(b))}">${nf(v,3)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="empty">${t('当前数据没有可分析的数值字段','No numeric columns are available')}</div>`}<div class="heatmap-note"><span style="color:#719451">●</span> ${t('正相关','Positive')} &nbsp; <span style="color:#b98a64">●</span> ${t('负相关','Negative')} &nbsp; · &nbsp; ${t('范围 −1 至 1，成对排除缺失值；常量列为 —。相关性不代表因果关系。','Range −1 to 1; missing values excluded pairwise. Constant columns show —. Correlation does not imply causation.')}</div></section>`;}
function chartsView(){const c=state.chart,cols=state.data.columns,nums=validCols();if(!cols.includes(c.x))c.x=cols[0];if(!nums.includes(c.y))c.y=nums[0]||cols[0];return `<div class="panel-grid"><section class="card control-card"><h2>${t('构建你的图表','Build your chart')}</h2>${selectField('chart-type',t('图表类型','Chart type'),['line','bar','scatter','histogram','donut'].map(k=>`<option value="${k}" ${c.type===k?'selected':''}>${({line:t('折线图','Line chart'),bar:t('柱状图','Bar chart'),scatter:t('散点图','Scatter plot'),histogram:t('直方图','Histogram'),donut:t('环形图','Donut chart')})[k]}</option>`).join(''))}${selectField('chart-x',t('X 轴 / 分类维度','X axis / dimension'),options(cols,c.x))}${selectField('chart-y',t('Y 轴 / 数值指标','Y axis / value'),options(nums,c.y))}${selectField('chart-agg',t('聚合方式','Aggregation'),aggs(c.agg))}${selectField('chart-group',t('日期汇总粒度','Date grouping'),[['month',t('按月','Monthly')],['day',t('按日','Daily')],['year',t('按年','Yearly')]].map(([k,v])=>`<option value="${k}" ${c.group===k?'selected':''}>${v}</option>`).join(''))}<button class="btn primary" data-action="draw">${icon('chart',15)}${t('更新图表','Update chart')}</button><button class="btn" data-action="export-chart">${icon('image',15)}${t('导出 SVG 图表','Export SVG chart')}</button><div class="info-box">${t('折线图观察趋势，柱状图比较分组，散点图发现关系，直方图查看分布，环形图展示占比。悬停图形查看数据。','Lines reveal trends; bars compare groups; scatter plots explore relationships; histograms show distributions; donuts show shares. Hover for details.')}</div></section><section class="card wide-chart"><div class="card-header"><div><div class="card-title">${esc(label(c.y))} ${c.type==='histogram'?t('分布','distribution'):`× ${esc(label(c.x))}`}</div><div class="card-subtitle">${nf(state.data.rows.length)} ${t('条记录 · 实时可视化','records · Live visualization')}</div></div><span class="pill">${c.type.toUpperCase()}</span></div><div class="chart-wrap">${customChart()}</div><div class="chart-footer">${icon('help',13)}${t('最多显示 30 个分组 / 2,000 个散点；缺失值不参与数值计算。环形图仅计入正值。','Shows up to 30 groups / 2,000 points. Numeric calculations skip missing values. Donuts use positive values only.')}</div></section></div>`;}
function helpView(){return `<div class="help-grid"><section class="card help-card"><h2>${t('01 / 导入自己的数据','01 / Bring your own data')}</h2><p>${t('点击“导入数据”，或拖拽文件到导入区域。支持 UTF-8 / GB18030 编码的 CSV、TSV 和 JSON 对象数组。首行为字段名，字段名需唯一且非空。建议不超过 20 MB、50,000 行、100 列。','Click Import data or drag a file into the import area. Supports CSV, TSV and JSON object arrays in UTF-8 / GB18030. The first row contains unique, non-empty column names. Limits: 20 MB, 50,000 rows, 100 columns.')}</p><p style="margin-top:10px">${t('JSON 格式示例：','Example JSON:')}<br><code>[{"region":"East","revenue":1200}]</code></p><button class="btn primary" data-action="import" style="margin-top:18px">${icon('upload',14)}${t('导入数据','Import data')}</button> <button class="btn" data-action="sample-export" style="margin-top:18px">${t('下载示例 CSV','Download sample CSV')}</button></section><section class="card help-card"><h2>${t('02 / 探索与清洗','02 / Explore & prepare')}</h2><ul><li>${t('搜索所有字段、条件筛选、表头排序、单元格编辑。','Search all fields, filter by condition, sort headers and edit cells.')}</li><li>${t('删除缺失行，均值 / 中位数 / 众数 / 指定值填充。','Drop missing rows; fill with mean, median, mode or a custom value.')}</li><li>${t('去重、转换类型、重命名、删列和创建计算列。','Deduplicate, convert types, rename, drop or compute columns.')}</li><li>${t('所有数据修改均可撤销；保留筛选结果会改变当前数据集。','Every data change is undoable. Keep filtered rows changes the active dataset.')}</li></ul></section><section class="card help-card"><h2>${t('03 / 分析与可视化','03 / Analyze & visualize')}</h2><ul><li>${t('描述统计提供均值、中位数、标准差、分位数等指标。','Descriptive statistics include mean, median, standard deviation and quantiles.')}</li><li>${t('分组聚合支持求和、均值、中位数、计数和极值。','Group by supports sum, mean, median, count and extrema.')}</li><li>${t('透视表交叉比较两个维度，相关性矩阵观察数值关系。','Pivot tables compare two dimensions; correlation matrices explore relationships.')}</li><li>${t('五类图表支持维度配置、日期汇总和 SVG 导出。','Five chart types support dimension selection, date grouping and SVG export.')}</li></ul></section><section class="card help-card"><h2>${t('04 / 保存与分享结果','04 / Save your findings')}</h2><p>${t('导出当前数据或筛选结果为 CSV / JSON，导出统计、分组和透视分析为 CSV，图表可保存为 SVG。语言切换保留相同数据和分析结果。','Export the dataset or filtered rows as CSV / JSON, statistical results as CSV, and charts as SVG. Switching language keeps the same data and results.')}</p><div class="info-box">${t('数据只保存在当前页面的内存中。刷新或关闭页面会恢复示例数据；请及时导出结果。导入新数据会替换当前数据并清空操作历史。','Data is held in this page’s memory. Reloading or closing restores the sample dataset; export your results first. Importing new data replaces the current dataset and clears its history.')}</div><p style="margin-top:12px">${t('本站参考 pandas 的常见功能实现浏览器端分析，并不执行 Python。示例数据为模拟学生学习成绩，包含 500 行、12 列、30 个缺失单元格和 10 条重复记录，仅用于展示。','This site implements common pandas-style workflows in the browser without executing Python. Sample data represents simulated student learning results: 500 rows, 12 columns, 30 missing cells and 10 duplicate records, for demonstration only.')}</p></section></div>`;}
